    "subprocessors.headline": {
        en: "Who else touches your data.",
        es: "Quién más toca tus datos.",
    },
    "subprocessors.intro": {
        en: "AGCONN relies on a small set of infrastructure providers to operate the platform. Each one sees only the data needed for its role and is named here so you can audit the chain end to end. Outside providers work under written terms. This page is the single source of truth — when it changes, the privacy policy is updated to match.",
        es: "AGCONN depende de un conjunto pequeño de proveedores de infraestructura para operar la plataforma. Cada uno ve únicamente los datos necesarios para su función y aparece aquí para que puedas auditar la cadena de extremo a extremo. Los proveedores externos trabajan bajo términos por escrito. Esta página es la fuente única de verdad — cuando cambia, la política de privacidad se actualiza para coincidir.",
    },
    "subprocessors.meta.title": { en: "Subprocessors — AGCONN", es: "Subprocesadores — AGCONN" },
    "subprocessors.meta.description": {
        en: "Every infrastructure provider AGCONN shares data with: name, purpose, data category, location, and link to the terms that apply.",
        es: "Cada proveedor de infraestructura con quien AGCONN comparte datos: nombre, propósito, categoría de datos, ubicación y enlace a los términos que aplican.",
    },
    "subprocessors.last_reviewed_label": { en: "Last reviewed", es: "Última revisión" },
